-- CHUNK 1: staging historis pengiriman
DROP TABLE IF EXISTS public.hist_staging;
CREATE TABLE public.hist_staging (
  d date, ticket_no text, branch_name text, branch_code text,
  item_name text, qty numeric, keterangan text, resi text, barcode text,
  type_barang text, status_request text, status_aset text, status_terkirim text,
  grp text
);

